type ProfilePatch = { name?: string; phone?: string };
type ProfileForm = { name: string | undefined; phone: string | undefined };

function buildPatch(form: ProfileForm): ProfilePatch {
  const patch: ProfilePatch = {};
  if (form.name !== undefined) patch.name = form.name;
  if (form.phone !== undefined) patch.phone = form.phone;
  return patch;
}

const stored = { name: "Ada", phone: "0803 555 0142" };
console.log({ ...stored, ...buildPatch({ name: "Ada Obi", phone: undefined }) });
console.log(buildPatch({ name: undefined, phone: undefined }));

