class Account {
  readonly owner: string;
  constructor(owner: string) {
    this.owner = owner;
  }
  close(): string {
    return `${this.owner}: closed`;
  }
}

class SavingsAccount extends Account {
  interestKobo = 0;
  override close(): string {
    return `${super.close()}, interest ₦${this.interestKobo / 100}`;
  }
}

const savings = new SavingsAccount("Ada");
savings.interestKobo += 12500;
console.log(savings.close());

